def split_legacy_other_incomes(apps, schema_editor):
    IncomeDeclaration = apps.get_model("plot_applications", "IncomeDeclaration")
    for row in list(IncomeDeclaration.objects.all()):
        if getattr(row, "member_description", ""):
            row.description = row.member_description
            row.save(update_fields=["description"])
        for slot in (1, 2, 3):
            desc = getattr(row, f"other_income_{slot}_description", "") or ""
            amount = getattr(row, f"other_income_{slot}_amount", None)
